bad_example:
resource "aws_instance" "node" {
  count = length(var.names)
  tags = { Name = var.names[count.index] }
}

good_example:
resource "aws_instance" "node" {
  for_each = toset(var.names)
  tags = { Name = each.key }
}

bad_example:
resource "aws_db_instance" "principal" {
  password = var.db_password # sensitive = true en la variable, pero igual queda en texto plano en el .tfstate
}
# y el .tfstate se commitea al repo por costumbre

good_example:
# backend remoto cifrado, .tfstate en .gitignore siempre
terraform {
  backend "s3" {
    bucket  = "mi-org-tfstate"
    encrypt = true
  }
}

bad_example:
terraform {
  required_providers {
    aws = { source = "hashicorp/aws" } # sin version: cualquiera puede terminar bajando una version distinta
  }
}

good_example:
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.40" }
  }
}
# + commitear .terraform.lock.hcl

bad_example:
provider "aws" {
  access_key = "AKIA..." # secreto real en el .tf, commiteado al repo
  secret_key = "wJal..."
}

good_example:
provider "aws" {
  region = "us-east-1"
  # credenciales via AWS_ACCESS_KEY_ID/AWS_SECRET_ACCESS_KEY en el entorno, o un rol asumido
}

containers:
  - name: api
    image: miapp:1.0
    resources:
      requests: { cpu: "250m", memory: "256Mi" }
      limits: { cpu: "500m", memory: "512Mi" }
